function Hash([string]$Path) { (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() }
function Read-Utf8([string]$Path) { [IO.File]::ReadAllText($Path) }
function Write-Utf8([string]$Path,[string]$Value) { [IO.File]::WriteAllText($Path,$Value,[Text.UTF8Encoding]::new($false)) }
function Backup-IfPresent([string]$Target,[string]$Backup,[string]$UserHome) { if(Test-Path -LiteralPath $Target){$relative=$Target.Substring($UserHome.Length).TrimStart('\');$copy=Join-Path $Backup $relative;New-Item -ItemType Directory -Force -Path (Split-Path -Parent $copy)|Out-Null;Copy-Item -LiteralPath $Target -Destination $copy -Force;return $copy};return $null }
$sourceSkills=Join-Path $VaultRoot 'vendor\maeos\curated\skills';$sourceReferences=Join-Path $VaultRoot 'vendor\maeos\curated\references';$referenceHome=Join-Path $CodexHome 'references\maeos'
$targets=@(Get-ChildItem -LiteralPath $sourceSkills -Directory|ForEach-Object{[pscustomobject]@{kind='skill';source=(Join-Path $_.FullName 'SKILL.md');target=(Join-Path $SkillsHome ($_.Name+'\SKILL.md'))}})
