  if(Test-Path -LiteralPath $entry.target){$current=Hash $entry.target;$desired=Hash $entry.source;if($current -ne $desired){$known=$previousFiles|Where-Object { [string]$_.destination -eq $entry.target }|Select-Object -First 1;if($null -eq $known -or [string]$known.sha256 -ne $current){throw "INSTALL_REFUSES_LOCAL_DRIFT: $($entry.target)"};$changes.Add($entry)}}else{$changes.Add($entry)}
}
$profileText=if(Test-Path -LiteralPath $profile){Read-Utf8 $profile}else{''};$configText=if(Test-Path -LiteralPath $config){Read-Utf8 $config}else{''}
