if(Test-Path -LiteralPath $profile){if(-not $profileText.Contains($profileDesired)){if($profileText.Contains('depth-one A7 routing and final acceptance') -or $profileText.Contains('Use Terra High only for an explicit integration-sensitive root decision')){$changes.Add([pscustomobject]@{kind='profile';source='managed merge';target=$profile})}else{throw "INSTALL_REFUSES_PROFILE_DRIFT: $profile"}}}
if(Test-Path -LiteralPath $config){if($configText.Contains($configOld)){$changes.Add([pscustomobject]@{kind='config';source='managed stale-hint merge';target=$config})}elseif(-not $configText.Contains($configDesired)){throw "INSTALL_REFUSES_CONFIG_DRIFT: $config"}}
$globalTarget=Join-Path $CodexHome 'AGENTS.md';$priorGlobal=$previousFiles|Where-Object { [string]$_.kind -eq 'global_agents' }|Select-Object -First 1
$globalExtension=Join-Path $CodexHome '.agents\PROJECT_POLICY.md';$priorExtension=$previousFiles|Where-Object { [string]$_.kind -eq 'global_extension' }|Select-Object -First 1
$accountCodexHome=Join-Path $env:USERPROFILE '.codex';$isAccountInstall=([IO.Path]::GetFullPath($CodexHome) -eq [IO.Path]::GetFullPath($accountCodexHome))
