$lean=if([string]::IsNullOrWhiteSpace($LeanConfigPath)){Join-Path $env:USERPROFILE '.config\lean-ctx\config.toml'}else{[IO.Path]::GetFullPath($LeanConfigPath)};$priorLean=$previousFiles|Where-Object { [string]$_.kind -eq 'lean_ctx_exact_allowance' }|Select-Object -First 1
$hooks=Join-Path $CodexHome 'hooks.json';$priorHooks=$previousFiles|Where-Object { [string]$_.kind -eq 'codex_hooks' }|Select-Object -First 1
$maeosVerificationScripts=@('D:\Documents\Codex\GitHub\gpt-context-vault\automation\codex-model-routing\inspect-codex-features.ps1','D:\Documents\Codex\GitHub\gpt-context-vault\automation\codex-model-routing\test-maeos-routing.ps1','D:\Documents\Codex\GitHub\gpt-context-vault\automation\codex-model-routing\test-maeos-install.ps1','D:\Documents\Codex\GitHub\gpt-context-vault\automation\codex-model-routing\verify-maeos.ps1','D:\Documents\Codex\GitHub\gpt-context-vault\automation\codex-model-routing\verify-token-optimization.ps1')
if(Test-Path -LiteralPath $hooks){$hooksText=Read-Utf8 $hooks;if((($isAccountInstall -and (Hash $hooks) -ne '226375248cb470fac3ea585bb9541962fcf9a9d98f95268d32cc8a20edd44344') -or -not $hooksText.Contains('hook codex-session-start') -or -not $hooksText.Contains('hook observe'))){throw 'INSTALL_REFUSES_HOOKS_DRIFT'}}
if($null -ne $previous){foreach($entry in @($previousFiles|Where-Object { @('profile','config','global_agents','global_extension','lean_ctx_exact_allowance','codex_hooks') -contains [string]$_.kind })){if((Test-Path -LiteralPath $entry.destination) -and ([string]$entry.sha256 -ne (Hash $entry.destination))){if([string]$entry.kind -eq 'codex_hooks' -and [string]$entry.sha256 -eq '16d406056b832a2f9c506a0191c6e37aa683134dfbf7083d9f46dab0b1fae77f' -and (Hash $entry.destination) -eq '226375248cb470fac3ea585bb9541962fcf9a9d98f95268d32cc8a20edd44344'){continue};if(([string]$entry.kind -eq 'config') -and ([string]$entry.sha256 -eq '41344795a48254ad50e053c6511bb91538ab49f1d6f44260b862d1ba36c07609') -and ((Hash $entry.destination) -eq 'cc0d00427dddbf53fc8cb8ab85d49a9aec5df1a8b331deb38128789bc0abfa20') -and ((Hash $globalExtension) -eq (Hash (Join-Path $VaultRoot 'governance\agents\extensions\global-codex.PROJECT_POLICY.md')))){continue};if(([string]$entry.kind -eq 'config') -and ([string]$entry.sha256 -eq '5a83b0376f4bf383e348c0054f3256770d4020a2d2da9afbb248ea7d088ca040') -and ((Hash $entry.destination) -eq '41344795a48254ad50e053c6511bb91538ab49f1d6f44260b862d1ba36c07609') -and ((Hash $globalExtension) -eq (Hash (Join-Path $VaultRoot 'governance\agents\extensions\global-codex.PROJECT_POLICY.md')))){continue};if([string]$entry.kind -eq 'global_agents' -and (Hash $entry.destination) -eq (Hash (Join-Path $VaultRoot 'AGENTS.md'))){continue};if([string]$entry.kind -eq 'global_extension' -and (Hash $entry.destination) -eq (Hash (Join-Path $VaultRoot 'governance\agents\extensions\global-codex.PROJECT_POLICY.md'))){continue};throw "INSTALL_REFUSES_LOCAL_DRIFT: $($entry.destination)"}}}
$priorConfig=$previousFiles|Where-Object { [string]$_.kind -eq 'config' }|Select-Object -First 1
$manifestNeedsUpdate=($null -eq $previous -or [int]$previous.schema_version -lt 3 -or ((Test-Path -LiteralPath $config) -and ($null -eq $priorConfig -or [string]$priorConfig.sha256 -ne (Hash $config))) -or ((Test-Path -LiteralPath $globalTarget) -and ($null -eq $priorGlobal -or [string]$priorGlobal.sha256 -ne (Hash $globalTarget))) -or ((Test-Path -LiteralPath $globalExtension) -and $null -eq $priorExtension) -or ((Test-Path -LiteralPath $lean) -and ($null -eq $priorLean -or [string]$priorLean.sha256 -ne (Hash $lean))) -or ((Test-Path -LiteralPath $hooks) -and ($null -eq $priorHooks -or [string]$priorHooks.sha256 -ne (Hash $hooks))))
$changeTargets=@($changes|ForEach-Object{[string]$_.target})
if($Mode -eq 'Plan'){
  [ordered]@{mode='Plan';codex_home=$CodexHome;managed_changes=@($changes|ForEach-Object target);manifest_update=$manifestNeedsUpdate;global_agents='MANAGED_BY_CANONICAL_SYNC_ONLY';backup='created only for Apply when files or manifest require update';real_codex_calls=0}|ConvertTo-Json -Depth 6;exit 0
}
if($changes.Count -eq 0 -and -not $manifestNeedsUpdate){[ordered]@{mode='Apply';status='NOOP';manifest=$manifestPath;real_codex_calls=0}|ConvertTo-Json;exit 0}
New-Item -ItemType Directory -Force -Path $backup|Out-Null
$backups=@{};foreach($change in $changes){$backups[$change.target]=Backup-IfPresent $change.target $backup $CodexHome};if(Test-Path -LiteralPath $manifestPath){$backups[$manifestPath]=Backup-IfPresent $manifestPath $backup $CodexHome}
foreach($entry in $targets){if($changeTargets -contains $entry.target){New-Item -ItemType Directory -Force -Path (Split-Path -Parent $entry.target)|Out-Null;Copy-Item -LiteralPath $entry.source -Destination $entry.target -Force}}
if($changeTargets -contains $profile){$next=$profileText.Replace('depth-one A7 routing and final acceptance','MAEOS-v1 profitable-delegation routing and final acceptance').Replace('at most 16 direct children','0..4 normal readers, graph-gated read-only bursts through 16 direct children').Replace('Use Terra Max only after an explicit Sol fallback/integration decision','Use Terra High as the native MAEOS writer, integration, and coordination lane for every non-Ox write; it remains subject to the root decision and one-writer lock.').Replace('Use Terra High only for an explicit integration-sensitive root decision, except HAU-USC frontend implementation where Terra Max is the sole writer.','Use Terra High as the native MAEOS writer, integration, and coordination lane for every non-Ox write; it remains subject to the root decision and one-writer lock.');Write-Utf8 $profile $next}
if($changeTargets -contains $config){Write-Utf8 $config ($configText.Replace($configOld,$configDesired))}
