$managed=@($files)
if(Test-Path -LiteralPath $profile){$managed+=[ordered]@{kind='profile';source='managed Unicode-safe merge';destination=$profile;sha256=(Hash $profile);pre_sha256=if($isAccountInstall){'60ee3f66d199379e2f67e2a6a0845191b1e4696f7faaa654e1de021852177c93'}else{$null};status='UPDATED_BY_MAEOS_V1';backup_path=if($isAccountInstall){$profileBaselineBackup}else{$backups[$profile]};rollback='restore exact baseline backup'}}
if(Test-Path -LiteralPath $config){$managed+=[ordered]@{kind='config';source='managed stale-A7-hint merge';destination=$config;sha256=(Hash $config);pre_sha256=if($isAccountInstall){'1936760cf133260e61fb8b8e5c4a149fbf117b855dc9f48c8154f9f65be00b4c'}else{$null};status='UPDATED_BY_MAEOS_V1';backup_path=if($isAccountInstall){$configBaselineBackup}else{$backups[$config]};rollback='restore exact baseline backup'}}
if(Test-Path -LiteralPath $hooks){$managed+=[ordered]@{kind='codex_hooks';source='verified existing user SessionStart hooks preserved; canonical LeanCTX block makes cached emission idempotent';destination=$hooks;sha256=(Hash $hooks);pre_sha256=if($isAccountInstall){'226375248cb470fac3ea585bb9541962fcf9a9d98f95268d32cc8a20edd44344'}else{$null};status='PRESERVED_EXISTING_SESSIONSTART_HOOKS';backup_path=if($isAccountInstall){Join-Path $accountBackup '.codex\hooks.json'}else{$backups[$hooks]};rollback='preserve existing hooks; restore exact backup only if explicitly requested'}}
if(Test-Path -LiteralPath $globalTarget){$managed+=[ordered]@{kind='global_agents';source='AGENTS.md';source_sha256=(Hash (Join-Path $VaultRoot 'AGENTS.md'));destination=$globalTarget;sha256=(Hash $globalTarget);pre_sha256=if($isAccountInstall){'9134072db442fc8e838b07434849701f4885a9c831d0b50a747103bc24f437b6'}else{$null};status='UPDATED_BY_CANONICAL_SYNC';backup_path=if($isAccountInstall){$globalBaselineBackup}else{$null};rollback='restore exact sync baseline backup'}}
if(Test-Path -LiteralPath $globalExtension){$extensionSource=Join-Path $VaultRoot 'governance\agents\extensions\global-codex.PROJECT_POLICY.md';$managed+=[ordered]@{kind='global_extension';source='governance/agents/extensions/global-codex.PROJECT_POLICY.md';source_sha256=(Hash $extensionSource);destination=$globalExtension;sha256=(Hash $globalExtension);pre_sha256=if($isAccountInstall){'5a3dd6e710cca1251e8b706c5087fac0a61fdfda7b4ce6c5375a86692ad875ae'}else{$null};status='UPDATED_BY_CANONICAL_SYNC';backup_path=if($isAccountInstall){$extensionBaselineBackup}else{$null};rollback='restore exact sync baseline backup'}}
if(Test-Path -LiteralPath $lean){if($isAccountInstall -and (-not (Test-Path -LiteralPath $leanBaselineBackup) -or (Hash $leanBaselineBackup) -ne 'f0e31f6f99df94c930034c76c2189b4dfb6ea8f60a5f780b6989aaa365382e55')){throw 'INSTALL_REFUSES_MISSING_OR_INVALID_LEAN_ROLLBACK'};$managed+=[ordered]@{kind='lean_ctx_exact_allowance';source='exact MAEOS verification script paths only';allowlisted_scripts=$maeosVerificationScripts;destination=$lean;sha256=(Hash $lean);pre_sha256='F0E31F6F99DF94C930034C76C2189B4DFB6EA8F60A5F780B6989AAA365382E55';status='INSTALLED_OR_PRESERVED';backup_path=if($isAccountInstall){$leanBaselineBackup}else{$backups[$lean]};rollback='restore verified exact backup; no shell-security weakening'}}
